class Solution {
public:
    int longestConsecutive(vector<int>& nums) {
        set<int> seen(nums.begin(), nums.end());
        int best = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (seen.count(nums[i] - 1)) continue;
            int cur = nums[i], len = 1;
            while (seen.count(cur + 1)) {
                cur++;
                len++;
            }
            best = max(best, len);
        }
        return best;
    }
};
